        if nums[i] < left_max:
            partition = i
            left_max = curr_max
        else:
            curr_max = max(curr_max, nums[i])
    return partition + 1

def findMissingRanges(nums, lower, upper):
    result = []
    prev = lower - 1
    for i in range(len(nums) + 1):
        curr = nums[i] if i < len(nums) else upper + 1
        if curr - prev == 2:
            result.append([prev + 1, prev + 1])
        elif curr - prev > 2:
