class RangeModule:
    def __init__(self):
        self.ranges = []  # sorted list of [start, end]

    def addRange(self, left, right):
        new = [left, right]
        result = []
        inserted = False
        for r in self.ranges:
            if r[1] < new[0]:  # r ends before new starts
                result.append(r)
            elif r[0] > new[1]:  # r starts after new ends
                if not inserted:
                    result.append(new)
                    inserted = True
                result.append(r)
            else:  # overlap — merge
                new[0] = min(new[0], r[0])
                new[1] = max(new[1], r[1])
        if not inserted:
            result.append(new)
        self.ranges = result

    def queryRange(self, left, right):
        for r in self.ranges:
            if r[0] <= left and right <= r[1]:
                return True
        return False

    def removeRange(self, left, right):
        result = []
        for r in self.ranges:
            if r[1] <= left or r[0] >= right:
                result.append(r)
            else:
                if r[0] < left:
                    result.append([r[0], left])
                if r[1] > right:
                    result.append([right, r[1]])
        self.ranges = result

