        self.intervals = []  # sorted by start

    def addNum(self, val):
        new = [val, val]
        result = []
        inserted = False
        for iv in self.intervals:
            if iv[1] + 1 < new[0]:  # iv ends before new (with gap)
                result.append(iv)
            elif iv[0] - 1 > new[1]:  # iv starts after new (with gap)
                if not inserted:
                    result.append(new)
                    inserted = True
                result.append(iv)
