def minTaps(n, ranges):
    max_reach = [0] * (n + 1)
    for i, r in enumerate(ranges):
        left = max(0, i - r)
        max_reach[left] = max(max_reach[left], i + r)
    taps = cur_end = far = 0
    for i in range(n + 1):
        if i > cur_end:
            return -1
        if i > far:
            taps += 1
            far = cur_end
        cur_end = max(cur_end, max_reach[i])
    return taps

