def splitPainting(segments):
    events = defaultdict(set)
    for l, r, c in segments:
        events[l].add(('add', c))
        events[r].add(('remove', c))
    points = sorted(events)
    result = []
    active = set()
    prev = None
    for p in points:
        if prev is not None and active:
            result.append([prev, p, frozenset(active)])
        for op, c in events[p]:
            if op == 'add':
                active.add(c)
            else:
                active.discard(c)
        prev = p
    return result

