def amountPainted(paint):
    # Simple approach with a painted set tracking endpoints
    # Using a workload-compression trick
    painted = {}
    result = []
    for s, e in paint:
        new_area = 0
        i = s
        while i < e:
            if i in painted:
                i = painted[i]  # jump to end of painted region
            else:
                new_area += 1
                painted[i] = i + 1
                i += 1
        # path compression
        i = s
        while i < e:
            nxt = painted[i]
            painted[i] = e
            i = nxt
        result.append(new_area)
    return result

